JOIN exercises e ON e.source = 'exercisedb' AND LOWER(e.name) = pairs.exercise_name
JOIN exercise_muscles m ON m.name = pairs.muscle_name
ON CONFLICT DO NOTHING;

-- --------------------------------------------------------
-- 8. Verification counts
-- --------------------------------------------------------
SELECT 'exercise_body_parts' AS table_name, COUNT(*) AS count FROM exercise_body_parts
UNION ALL SELECT 'exercise_muscles', COUNT(*) FROM exercise_muscles
UNION ALL SELECT 'exercise_equipments', COUNT(*) FROM exercise_equipments
UNION ALL SELECT 'exercise_secondary_muscles', COUNT(*) FROM exercise_secondary_muscles
UNION ALL SELECT 'exercises_with_body_part', COUNT(*) FROM exercises WHERE body_part_id IS NOT NULL
UNION ALL SELECT 'exercises_with_target_muscle', COUNT(*) FROM exercises WHERE target_muscle_id IS NOT NULL
UNION ALL SELECT 'exercises_with_equipment', COUNT(*) FROM exercises WHERE equipment_id IS NOT NULL;

COMMIT;
